\begin{tikzpicture}
\begin{axis}[
    width=0.72\textwidth,
    height=0.48\textwidth,
    xmin=-2.1, xmax=2.1,
    ymin=-1.6, ymax=5.2,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,-1,0,1,2},
    ytick={-1,0,1,2,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-2:2, samples=180] {x^4-3*x^2+2};
\addplot[very thick, domain=-0.4:1.8, samples=2] {-2*x+2};
\addplot[only marks, mark=*] coordinates {(1,0)};
\node[fill=white, inner sep=1pt, anchor=south west] at (axis cs:1.08,0.12) {\((1,0)\)};
\node[fill=white, inner sep=1pt, anchor=south] at (axis cs:0.0,3.15) {\(p(x)=x^4-3x^2+2\)};
\node[fill=white, inner sep=1pt, anchor=north] at (axis cs:0.35,-0.45) {tangent slope \(-2\)};
\end{axis}
\end{tikzpicture}
